'use strict';
const clone=x=>JSON.parse(JSON.stringify(x));
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function transportText(text){text=text.replace(/비츠나우\s*→\s*(?:🚢\s*|유람선 이동\s*·\s*)?유람선으로\s*루체른/g,'유람선 이동 · 비츠나우 → 루체른');return text.replace(/🚆🚌/g,'기차·버스 이동 · ').replace(/✈️?/g,'항공 이동 · ').replace(/🚆/g,'기차 이동 · ').replace(/🚌/g,'버스 이동 · ').replace(/🚇/g,'지하철 이동 · ').replace(/🚕/g,'택시 이동 · ').replace(/🚶/g,'도보 이동 · ').replace(/🚞/g,'산악열차 이동 · ').replace(/🚠/g,'곤돌라 이동 · ').replace(/🚡/g,'케이블카 이동 · ').replace(/🚢/g,'유람선 이동 · ').replace(/🚵/g,'트로티바이크 이동 · ').replace(/케이블카 이동 · \s*(?=Sunnegga)/g,'');}
function normalizeTransport(d){d.days.forEach(day=>day.events.forEach(e=>e.text=transportText(e.text)));return d;}
const hotelPhotos=window.HOTEL_PHOTOS||{};
function selectedHotelPhotos(h){const photo=hotelPhotos[h.name];if(!photo)return null;const key=(h.room||'').trim().toLowerCase();return {...photo,roomFile:(photo.requested||photo.match?.includes(key))?photo.roomFile:null};}
function hotelPhoto(h){const photo=selectedHotelPhotos(h);if(!photo)return '';const i=data.hotels.indexOf(h);return `<div class="hotel-pair"><figure><button class="photo-expand" data-action="hotel-photo" data-index="${i}" data-kind="exterior" aria-label="${esc(h.name)} 건물 전경 크게 보기"><img src="photos/${photo.exterior}" alt="${esc(h.name)} 건물 전경" loading="lazy"></button><figcaption>건물 전경</figcaption></figure><figure>${photo.roomFile?`<button class="photo-expand" data-action="hotel-photo" data-index="${i}" data-kind="room" aria-label="${esc(photo.roomName)} 객실 사진 크게 보기"><img src="photos/${photo.roomFile}" alt="${esc(photo.roomName)} 공식 객실 사진" loading="lazy"></button><figcaption>${photo.requested?'희망 객실':'객실'}</figcaption>`:'<div class="photo-pending">객실 사진<br>세부 타입 확인 중</div>'}</figure></div>`;}
const native=window.TripNative;
let data=clone(window.INITIAL_DATA),prefs={edit:false,large:false,auth:null,theme:'dark',photoCache:[],weather:{},fx:null,view:'calendar'},tab='today',dayIndex=0;
function valid(d){return d&&d.version===1&&Array.isArray(d.days)&&d.days.length===15&&d.days.every((a,i)=>a.date===INITIAL_DATA.days[i].date&&typeof a.city==='string'&&Array.isArray(a.events)&&a.events.length<300&&a.events.every(e=>typeof e.id==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(e.time)&&typeof e.text==='string'&&e.text.length<5001&&typeof e.done==='boolean'))&&Array.isArray(d.hotels)&&d.hotels.length===7&&d.hotels.every(h=>typeof h.id==='string'&&typeof h.name==='string'&&typeof h.city==='string'&&/^2027-\d{2}-\d{2}$/.test(h.checkin)&&/^2027-\d{2}-\d{2}$/.test(h.checkout))&&Array.isArray(d.checklist)&&d.checklist.length<500&&d.checklist.every(c=>typeof c.id==='string'&&typeof c.text==='string'&&typeof c.done==='boolean')&&typeof d.notes==='string'&&Array.isArray(d.flights)&&d.flights.length===2;}
const sheetSync={enabled:!!window.TripSheet,busy:false,last:'',error:''};
let loadError=false;
try{const raw=native?native.load():localStorage.getItem('europe-trip-v1');if(raw){const s=JSON.parse(raw);if(!valid(s.data))throw Error();data=s.data;prefs={edit:!!s.prefs?.edit,large:!!s.prefs?.large,theme:s.prefs?.theme==='light'?'light':'dark',sheetUrl:typeof s.prefs?.sheetUrl==='string'?s.prefs.sheetUrl:'',auth:s.prefs?.auth&&typeof s.prefs.auth.pw==='string'&&(s.prefs.auth.role==='owner'||s.prefs.auth.role==='mom')?s.prefs.auth:null,photoCache:Array.isArray(s.prefs?.photoCache)?s.prefs.photoCache:[],view:['calendar','route','list'].includes(s.prefs?.view)?s.prefs.view:'calendar',weather:s.prefs?.weather&&typeof s.prefs.weather==='object'?s.prefs.weather:{},fx:s.prefs?.fx&&typeof s.prefs.fx==='object'?s.prefs.fx:null,sheetLastSync:s.prefs?.sheetLastSync||'',beforeSheet:s.prefs?.beforeSheet};}}catch(e){loadError=true;}
normalizeTransport(INITIAL_DATA);normalizeTransport(data);sheetSync.last=prefs.sheetLastSync||'';
const today=new Date().toLocaleDateString('en-CA');const ti=data.days.findIndex(d=>d.date===today);if(ti>=0)dayIndex=ti;
function save(){try{const s=JSON.stringify({data,prefs});if(native){if(!native.save(s))throw Error();}else localStorage.setItem('europe-trip-v1',s);return true;}catch(e){toast('저장 공간을 확인해 주세요. 변경 내용을 저장하지 못했어요.');return false;}}
