function render(){const dark=prefs.theme!=='light';document.documentElement.classList.toggle('large',prefs.large);document.documentElement.classList.toggle('dark',dark);document.querySelector('meta[name=theme-color]')?.setAttribute('content',dark?'#121417':'#eef5f6');try{native?.theme?.(dark);}catch(e){}document.querySelector('#app').innerHTML=`<header class="top"><div class="brand">엄마와 유럽<span>${tripLabel()}</span></div><div class="top-actions"><button class="theme-btn" data-action="theme" aria-label="${dark?'밝은 화면으로 바꾸기':'어두운 화면으로 바꾸기'}"><svg viewBox="0 0 24 24" aria-hidden="true">${dark?'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>':'<path d="M20 14.5A8 8 0 0 1 9.5 4 8 8 0 1 0 20 14.5z"/>'}</svg></button>${modeButton()}</div></header><main>${syncBanner()}${requestBar()}${({today:renderToday,schedule:renderSchedule,stay:renderStay,prepare:renderPrepare,more:renderMore}[tab]||renderToday)()}</main><nav class="nav" aria-label="주 메뉴">${Object.entries({today:'오늘',schedule:'일정',stay:'예약',prepare:'준비',more:'더보기'}).map(([k,v])=>`<button data-tab="${k}" class="${tab===k?'active':''}" ${tab===k?'aria-current="page"':''}><svg viewBox="0 0 24 24" aria-hidden="true">${icons[k]}</svg>${v}</button>`).join('')}</nav>`;if(tab==='schedule'){document.querySelector('.date.selected')?.scrollIntoView({block:'nearest',inline:'center'});}}
