function splitTransport(text){text=String(text);const m=text.match(modeRe);return m?{mode:m[1],text:text.replace(m[0],'').trim()}:{mode:null,text};}
const arrows=s=>esc(s).replace(/[ \t]*→[ \t]*/g,' <span class="arr">→</span>&nbsp;').trim();
function dateLong(s){const [y,m,d]=s.split('-');return `${Number(m)}월 ${Number(d)}일 ${weekdays[new Date(y,m-1,d).getDay()]}요일`;}
const heroArt={swiss:'<svg class="hero-art" viewBox="0 0 320 200" aria-hidden="true"><circle cx="262" cy="50" r="17" fill="#f5d28a"/><path d="M-10 200 110 22 230 200Z" fill="#dfe7f5"/><path d="m110 22-34 50 34-13 25 11Z" fill="#fff"/><path d="M120 200 230 72 340 200Z" fill="#9fb2d6"/><path d="m230 72-22 26 22-8 18 9Z" fill="#fff"/><path d="M-10 184Q70 146 160 182T330 170V200H-10Z" fill="#5f79a8"/></svg>',spain:'<svg class="hero-art" viewBox="0 0 320 200" aria-hidden="true"><circle cx="232" cy="76" r="36" fill="#ffd27a"/><path d="M-10 200V164Q80 128 170 152T330 144V200Z" fill="#f0a067"/><path fill-rule="evenodd" d="M140 112h180v88H140zM152 200v-50a20 20 0 0 1 40 0v50zM204 200v-50a20 20 0 0 1 40 0v50zM256 200v-50a20 20 0 0 1 40 0v50z" fill="#fde3c8"/><path d="M134 104h192v10H134z" fill="#fde3c8"/></svg>'};
const flags={swiss:'<svg viewBox="0 0 16 16" aria-hidden="true"><rect width="16" height="16" rx="3" fill="#d52b1e"/><path d="M6.5 3.5h3v3h3v3h-3v3h-3v-3h-3v-3h3z" fill="#fff"/></svg>',spain:'<svg viewBox="0 0 16 16" aria-hidden="true"><rect width="16" height="16" rx="3" fill="#c60b1e"/><rect y="4" width="16" height="8" fill="#ffc400"/></svg>'};
function dayHero(d){const c=dayIndex>=6?'spain':'swiss';return `<section class="day-hero ${c}"><div class="hero-top"><span class="flag">${flags[c]}${c==='spain'?'스페인':'스위스'}${dayIndex===6?' · 이동일':''}</span><span>${dayIndex+1}일째 / ${data.days.length}일</span></div><div class="hero-day"><span class="day-label">DAY</span><span class="day-no">${String(dayIndex+1).padStart(2,'0')}</span></div><h1>${arrows(d.city)}</h1><p>${dateLong(d.date)}</p>${heroArt[c]}<div class="hero-progress" aria-label="${data.days.length}일 중 ${dayIndex+1}일째">${data.days.map((_,i)=>`<i class="${i<=dayIndex?'on':''}"></i>`).join('')}</div></section>`;}
function tonight(d){const h=data.hotels.find(h=>h.checkin<=d.date&&d.date<h.checkout);if(!h)return '';const i=data.hotels.indexOf(h),p=selectedHotelPhotos(h);return `<div class="tonight">${p?`<img src="photos/${p.exterior}" alt="" loading="lazy">`:`<span class="tonight-icon"><svg viewBox="0 0 24 24" aria-hidden="true">${icons.stay}</svg></span>`}<div class="tonight-text"><small>오늘 밤 숙소</small><strong>${esc(h.name||h.city+' · 숙소 미정')}</strong></div><button data-action="hotel-map" data-index="${i}">길찾기 ↗</button></div>`;}
function nextIndex(d){if(dayIndex!==ti)return {i:-1};const hm=new Date().toTimeString().slice(0,5);let k=-1;d.events.forEach((e,i)=>{if(e.time<=hm)k=i;});if(k>=0)return {i:k,label:'지금 일정'};return {i:d.events.length?0:-1,label:'다음 일정'};}
function dayNav(){const p=data.days[dayIndex-1],n=data.days[dayIndex+1];return `<nav class="day-nav" aria-label="다른 날 보기">${p?`<button data-jump="${dayIndex-1}"><small>← 전날</small>${dateLabel(p.date)}</button>`:'<span></span>'}${n?`<button class="next-day" data-jump="${dayIndex+1}"><small>다음 날 →</small>${dateLabel(n.date)}</button>`:'<span></span>'}</nav>`;}
const photoReady=()=>!!native?.photoReady?.();
let pendingPhotos=[];
function readQueue(){try{pendingPhotos=native?JSON.parse(native.queueState()):[];}catch(e){pendingPhotos=[];}}
function photosOfDay(day){const remote=(prefs.photoCache||[]).filter(p=>p.day===day);const ids=new Set(remote.map(p=>p.id));return remote.concat(pendingPhotos.filter(p=>p.day===day&&!ids.has(p.id)).map(p=>({...p,pending:true})));}
function thumb(p){return p.pending?`<span class="ph pending"><img src="${p.local||'/photo-local?id='+encodeURIComponent(p.id)}" alt="" loading="lazy"><i>올리는 중</i></span>`:`<button class="ph" data-action="photo-view" data-pid="${esc(p.id)}" aria-label="사진 크게 보기"><img src="${thumbUrl(p.fileId,400)}" alt="" loading="lazy"></button>`;}
function photoStrip(list){if(!list.length)return '';return `<div class="ph-strip">${list.slice(0,4).map(thumb).join('')}${list.length>4?`<button class="ph more" data-action="day-photos">+${list.length-4}</button>`:''}</div>`;}
function slotFor(day,hm){const times=(data.days.find(d=>d.date===day)?.events||[]).map(e=>e.time).sort();let t='';times.forEach(x=>{if(x<=hm)t=x;});return t||times[0]||'';}
function dayPhotos(d){const all=photosOfDay(d.date),times=new Set(d.events.map(e=>e.time)),loose=all.filter(p=>!times.has(p.time)),saved=all.filter(p=>!p.pending).length;const note=!native?'<p class="sub">사진 추가는 휴대폰 앱에서 할 수 있어요.</p>':!photoReady()?'<p class="sub">사진 공유는 구글 드라이브 연결을 마치면 켜져요.</p>':'';return `<section class="day-photos"><div class="dp-head"><div><h3>이 날 사진</h3><small>${all.length?all.length+'장':'아직 없어요'}</small></div>${photoReady()?'<button class="primary" data-action="add-photos">사진 추가</button>':''}</div>${note}${photoStrip(loose)}${saved&&native?'<button class="secondary full" data-action="save-day-photos">이 날 사진 모두 폰에 저장</button>':''}</section>`;}
function updateHint(){document.querySelector('.more-hint')?.classList.toggle('hide',window.scrollY>60);}
function rerenderKeep(){if(modal.open||document.activeElement?.matches('input,textarea,select'))return;const y=window.scrollY;render();window.scrollTo(0,y);updateHint();}
const PLACES={'취리히':[47.37,8.54,12,23],'루체른':[47.05,8.31,12,23],'그린델발트':[46.62,8.04,8,19],'체르마트':[46.02,7.75,6,18],'몽트뢰':[46.43,6.91,13,24],'제네바':[46.2,6.14,13,25],'세비야':[37.39,-5.98,19,33],'그라나다':[37.18,-3.6,15,30],'바르셀로나':[41.39,2.17,19,26]};
const PEAKS=[[/융프라우/,'융프라우요흐',-3,3],[/고르너그라트/,'고르너그라트',0,8],[/리기/,'리기 쿨름',6,14],[/First|피르스트/,'피르스트',5,14]];
const wxIcons={sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',cloud:'<path d="M7 18h10a4 4 0 0 0 .5-8A6 6 0 0 0 6 9.5 4.3 4.3 0 0 0 7 18z"/>',rain:'<path d="M7 15h10a4 4 0 0 0 .5-8A6 6 0 0 0 6 6.5 4.3 4.3 0 0 0 7 15zM8 18l-1 3m5-3-1 3m5-3-1 3"/>',snow:'<path d="M7 15h10a4 4 0 0 0 .5-8A6 6 0 0 0 6 6.5 4.3 4.3 0 0 0 7 15zM8 19h.01M12 21h.01M16 19h.01"/>'};
const wxKind=c=>c<=1?'sun':c<=48?'cloud':(c>=71&&c<=77)||c===85||c===86?'snow':'rain';
const wxLabel={sun:'맑음',cloud:'흐림',rain:'비',snow:'눈'};
function placeOf(d){for(const s of d.city.split('→').map(x=>x.trim()).reverse())for(const k in PLACES)if(s.includes(k))return k;return null;}
const topic=w=>{const c=w.charCodeAt(w.length-1)-0xAC00;return c>=0&&c<11172&&c%28?'은':'는';};
const isoToday=()=>new Date().toLocaleDateString('en-CA');
function addDays(s,n){const d=new Date(s+'T12:00:00');d.setDate(d.getDate()+n);return d.toLocaleDateString('en-CA');}
const shortDate=s=>/^\d{4}-\d\d-\d\d$/.test(s||'')?`${Number(s.slice(5,7))}월 ${Number(s.slice(8))}일`:'';
function weatherCard(d){
 const place=placeOf(d);if(!place)return '';const [,,lo,hi]=PLACES[place],f=prefs.weather?.[d.date];
 const min=f?Math.round(f.min):lo,max=f?Math.round(f.max):hi,kind=f&&typeof f.code==='number'?wxKind(f.code):null,text=d.events.map(e=>e.text).join(' '),tips=[];
 PEAKS.forEach(([re,name,a,b])=>{if(re.test(text))tips.push(`${name}${topic(name)} ${Number(d.date.slice(5,7))}월 평균 ${a}~${b}°예요. 패딩·장갑 챙기기`);});
 if(min<=8)tips.push('아침저녁이 쌀쌀해요. 겉옷 챙기기');
 if(f&&f.rain>=50)tips.push(`비 올 확률 ${f.rain}%. 우산 챙기기`);
 if(max>=30)tips.push('더워요. 모자·물·선크림 챙기기');
 if(!tips.length)tips.push('걷기 좋은 날씨예요. 편한 신발이면 충분해요');
 return `<section class="wx"><div class="wx-top"><span class="wx-icon">${kind?`<svg viewBox="0 0 24 24" aria-hidden="true">${wxIcons[kind]}</svg>`:'<b>평균</b>'}</span><div class="wx-main"><small>${esc(place)} · ${f?'일기예보':Number(d.date.slice(5,7))+'월 평균 기온'}</small><strong>${min}° <span>/</span> ${max}°${kind?` <em>${wxLabel[kind]}</em>`:''}</strong></div></div><ul class="wx-tips">${tips.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${f?'':'<p class="wx-note">여행 16일 전부터 실제 예보로 바뀌어요.</p>'}</section>`;}
let wxAt=0;
async function fetchWeather(){
 if(Date.now()-wxAt<30*60e3)return;
 const today=isoToday(),last=addDays(new Date().toISOString().slice(0,10),14),groups={};
 data.days.forEach(d=>{if(d.date<today||d.date>last)return;const p=placeOf(d);if(p)(groups[p]=groups[p]||[]).push(d.date);});
 const next={...prefs.weather};let changed=false;
 for(const [place,dates] of Object.entries(groups)){
  try{const [lat,lon]=PLACES[place];const r=await fetch(`/weather?lat=${lat}&lon=${lon}&start=${dates[0]}&end=${dates.at(-1)}`,{cache:'no-store'});if(!r.ok)continue;const dl=(await r.json()).daily;if(!dl||!Array.isArray(dl.time))continue;
   dl.time.forEach((t,i)=>{const mn=dl.temperature_2m_min?.[i],mx=dl.temperature_2m_max?.[i];if(!dates.includes(t)||typeof mn!=='number'||typeof mx!=='number')return;next[t]={min:mn,max:mx,rain:dl.precipitation_probability_max?.[i]??0,code:dl.weather_code?.[i]??null};changed=true;});
  }catch(e){}
 }
 if(changed){wxAt=Date.now();prefs.weather=next;save();rerenderKeep();}
}
