const KO=[[/First Cliff Walk/g,'피르스트 절벽 산책로'],[/\bFirst\b/g,'피르스트'],[/La Roca Village/g,'라 로카 빌리지 아울렛'],[/\bALSA\b/g,'알사 고속버스'],[/Aerobus\s*/g,'공항버스 '],[/EA버스/g,'공항버스'],[/Sunnegga 푸니쿨라/g,'수네가 산악 열차'],[/Sunnegga/g,'수네가'],[/(\d+)h(\d+)/g,'$1시간 $2분'],[/(\d+)h\b/g,'$1시간']];
const koreanize=s=>KO.reduce((t,[re,to])=>t.replace(re,to),s).replace(/\s+\)/g,')');
const RIDE={'기차':'기차 타고','버스':'버스 타고','항공':'비행기 타고','지하철':'지하철 타고','택시':'택시 타고','도보':'걸어서','산악열차':'산악열차 타고','곤돌라':'곤돌라 타고','케이블카':'케이블카 타고','유람선':'유람선 타고','트로티바이크':'트로티바이크 타고','기차·버스':'기차·버스 타고'};
const ro=w=>{const c=w.charCodeAt(w.length-1)-0xAC00;return c>=0&&c<11172&&c%28&&c%28!==8?'으로':'로';};
function splitTop(s,sep){const out=[];let depth=0,cur='';for(let i=0;i<s.length;i++){const ch=s[i];if(ch==='(')depth++;if(ch===')')depth=Math.max(0,depth-1);if(!depth&&s.startsWith(sep,i)){out.push(cur);cur='';i+=sep.length-1;continue;}cur+=ch;}out.push(cur);return out.map(x=>x.trim());}
function moveTitle(mode,text){
 const lines=text.split('\n');let first=lines[0].trim();if(first.startsWith(mode+' '))first=first.slice(mode.length+1);
 const segs=splitTop(first,'·'),k=segs.findIndex(x=>splitTop(x,'→').length>1);if(k<0)return null;
 const stops=splitTop(segs[k],'→'),notes=[];
 const pull=x=>{let t=x;const m=t.match(/^(.*?)\s*\(([^)]*)\)$/);if(m){t=m[1];notes.push(m[2]);}const tm=t.match(/^(.*?)\s+(\d{1,2}:\d\d)$/);return tm?{name:tm[1],time:tm[2]}:{name:t,time:''};};
 const from=pull(stops[0]),to=pull(stops.at(-1)),via=stops.slice(1,-1).map(x=>pull(x).name).filter(Boolean);
 let dest=to.name;if(/ 하산$/.test(dest)){dest=dest.replace(/ 하산$/,'');notes.unshift('내려오기');}
 if(!dest)return null;
 const sub=[...segs.slice(0,k),from.name?`${from.name}${from.time?' '+from.time:''} 출발`:'',via.length?`${via.join(', ')} 거쳐서`:'',to.time?`${to.time} 도착`:'',...notes.filter(n=>n!==mode),...segs.slice(k+1),...lines.slice(1).map(l=>l.trim().replace(/^\((.*)\)$/,'$1'))].filter(Boolean);
 return {title:`${RIDE[mode]||mode+' 타고'} ${dest.replace(/ /g,'\u00a0')}${ro(dest)}`,sub:sub.join(' · '),from:from.name,dest};
}
