function evInfo(e){const t=splitTransport(e.text),shown=koreanize(cityNames(t.text)),mv=t.mode?moveTitle(t.mode,shown):null,lines=shown.split('\n');return {mode:t.mode,shown,mv,title:mv?mv.title:lines[0],sub:mv?mv.sub:lines.slice(1).map(l=>l.trim().replace(/^\((.*)\)$/,'$1')).filter(Boolean).join(' · '),icon:t.mode?modeIcons[MODES[t.mode]]:''};}
function evKind(info){if(info.mode)return 'mv';const s=info.shown;if(/아침|점심|저녁|야식|식사|타파스|빠에야/.test(s))return 'eat';if(/체크인|체크아웃|휴식|자유|취침|기상|짐|낮잠|시에스타|대기/.test(s))return 'rest';return 'see';}
function spans(d){const ev=d.events;return ev.map((e,i)=>{const h=Number(e.time.slice(0,2)),nh=i<ev.length-1?Number(ev[i+1].time.slice(0,2)):h+1;return Math.min(3,Math.max(1,nh-h));});}
